function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  const seen = new Array(nums.length).fill(false);
  for (const value of nums) {
    if (!Number.isInteger(value) || value < 0 || value >= nums.length) return 'Each value is between 0 and nums.length - 1.';
    if (seen[value]) return 'The values of nums must be distinct.';
    seen[value] = true;
  }
  return null;
}

