function buildArray(nums) {
  const n = nums.length;
  for (let i = 0; i < n; i++) {
    const target = nums[i];
    const finalValue = nums[target] % n;
    nums[i] = target + finalValue * n;
  }
  for (let i = 0; i < n; i++) {
    nums[i] = Math.floor(nums[i] / n);
  }
  return nums;
}

