function generate(rand, size) {
  const n = size === 'large' ? 1000 - Math.floor(rand() * 50) : 1 + Math.floor(rand() * 8);
  const nums = Array.from({ length: n }, (_, i) => i);
  const shape = rand();
  if (shape < 0.1) return [nums];
  if (shape < 0.2) return [nums.reverse()];
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
